{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "Withaferin A, a structurally related polycyclic steroidal lactone, showed poor oral bioavailability in humans; its very high transfer score and shared terpenoid scaffold strongly support low oral F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Fluticasone had negligible (<1%) absolute bioavailability via gastrointestinal absorption in humans, demonstrating that a lipophilic fused-ring steroid with polar substituents can be essentially non-absorbed orally; this transfers strongly to the query's similar physicochemical profile.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Rifaximin was confirmed to be <0.4% orally bioavailable in healthy volunteers, providing direct human evidence that a complex polycyclic, polar natural product can have extremely low oral absorption; the high transfer score supports low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Sitostanol absolute oral bioavailability was only 0.04% in healthy subjects using an IV isotope reference, a direct quantitative human F measurement for a plant sterol/terpenoid; this is a strong quantitative anchor for low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Docetaxel has low absolute oral bioavailability in humans due to hepatic and intestinal first-pass extraction; the query's ester and hydroxyl groups are similarly susceptible to first-pass metabolism, supporting low F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues are complex polycyclic terpenoids/steroids with poor, very low, or negligible oral bioavailability in humans, including direct absolute F measurements below 1%. The query shares the same structural class and polar functionality, so low oral bioavailability is strongly supported.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the exact query molecule.",
    "Most supporting records are qualitative or route-specific rather than full absolute F values.",
    "No experimental data address whether the acetate or carboxylic acid groups alter absorption or first-pass metabolism relative to the analogues."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

